export default function About(){return <main className="publication"><div className="concept-banner">Fictional publication / Design prototype</div><div className="shell"><nav className="publication-nav" aria-label="Publication navigation"><Link className="publication-name" href={editorialRoot}>Perspective</Link><div><Link href={`${editorialRoot}#stories`}>Stories</Link><Link href={`${editorialRoot}#topics`}>Topics</Link></div></nav><section className="concept-heading"><p className="kicker">About the concept</p><h1>A place for a different perspective.</h1><p className="lead">Perspective is a fictional publication created to explore editorial hierarchy, responsive design and a clear reading flow. All three articles are sample editorial content. The portraits are generated conceptual imagery.</p><p className="lead">This prototype does not collect newsletter subscriptions or personal data. It has not been tested with readers.</p><div className="actions"><Link className="btn" href={editorialRoot}>Explore the stories</Link><Link className="text-link" href="/work/editorial-experience">Read the design study</Link></div></section></div></main>}
